mapper.select:
SELECT e.id, e.school_id, e.term_id, e.exam_name, e.exam_type, e.exam_date, e.grade_ids, e.status, e.created_at, e.updated_at FROM exam e WHERE e.deleted = 0
AND e.school_id = #{request.schoolId}
AND e.term_id = #{request.termId}
AND e.exam_name LIKE CONCAT('%', #{request.examName}, '%')
AND e.exam_type = #{request.examType}
AND e.status = #{request.status}
AND ',' || translate(e.grade_ids, '[] ', '') || ',' LIKE CONCAT('%,', #{request.gradeId}, ',%')
AND e.exam_date >= #{request.startDate}
AND e.exam_date <= #{request.endDate}
ORDER BY ${request.orderBy}
ASC
DESC
ORDER BY e.exam_date DESC, e.created_at DESC
